pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint8 _decimals, uint16 _feeRate) public {
        _feeRate = uint16(bound(_feeRate, 0, 5000));
        vm.prank(address(this));
        c.initialize(
            address(0x1),
            address(0x2),
            100,
            200,
            1,
            _feeRate,
            bytes32(0),
            false,
            false
        );
        assertTrue(c.initialized());
        vm.prank(address(this));
        try c.initialize(
            address(0x3),
            address(0x4),
            300,
            400,
            1,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            assertTrue(false);
        } catch {
            assertTrue(true);
        }
    }
}
